mapper.select:
select * from ( SELECT rrc.REPORT_CHECK_ID reportCheckId, rrc.REP_ID repId, rrc.REPORT_TYPE reportType, rrc.REPORT_NAME reportName , rri.P_PROD_ID pprodId, rri.PROD_ID prodId, rri.PROD_NAME prodName, rrc.CHECK_DATE checkDate, rrc.ERRORMSG errormsg, rrc.FILE_NO fileNo, rrc.UPDATE_TIME updateTime, rrc.CREATE_TIME createTime FROM REP_REPORT_CHECK rrc inner join REP_PROD_INFO rri on rrc.PROD_ID=rri.PROD_ID and rri.REP_PROD_TYPE in('02','03') where rrc.DATA_STATUS ='E'
AND (rri.PROD_ID IN
#{item}
or rri.P_PROD_ID IN
#{item} )
AND rrc.REPORT_TYPE IN
#{item}
AND rrc.REPORT_NAME IN
#{item}
AND rrc.CHECK_DATE >= TO_DATE(#{checkDateStart},'YYYY-MM-DD')
AND rrc.CHECK_DATE <= TO_DATE(#{checkDateEnd},'YYYY-MM-DD')
union all SELECT rrc.REPORT_CHECK_ID reportCheckId, rrc.REP_ID repId, rrc.REPORT_TYPE reportType, rrc.REPORT_NAME reportName , rri.PROD_ID pprodId, '' prodId, rri.PROD_NAME prodName, rrc.CHECK_DATE checkDate, rrc.ERRORMSG errormsg, rrc.FILE_NO fileNo, rrc.UPDATE_TIME updateTime, rrc.CREATE_TIME createTime FROM REP_REPORT_CHECK rrc inner join REP_PROD_INFO rri on rrc.PROD_ID=rri.PROD_ID and rri.REP_PROD_TYPE in('01') where rrc.DATA_STATUS ='E'
AND (rri.PROD_ID IN
#{item}
or rri.P_PROD_ID IN
#{item} )
AND rrc.REPORT_TYPE IN
#{item}
AND rrc.REPORT_NAME IN
#{item}
AND rrc.CHECK_DATE >= TO_DATE(#{checkDateStart},'YYYY-MM-DD')
AND rrc.CHECK_DATE <= TO_DATE(#{checkDateEnd},'YYYY-MM-DD')
) order by NVL(updateTime,createTime) desc

mapper.delete:
delete from rep_report_check rrc where 1=1
AND rrc.REPORT_CHECK_ID IN
